/* Types */
/**  핸드셰이크로 확인한 상대편 정보. 프런트가 "무엇에 붙었는지" 보여준다. */
export type AcpAgentInfo = {
	name: string,
	title: string | null,
	version: string,
	/**
	 *  `authMethods` 가 비어 있지 않으면 별도 인증 흐름이 필요하다는 뜻 —
	 *  2026-08-14 실측은 빈 배열(구독 로그인 재사용)이었다.
	 */
	auth_required: boolean,
};

/**  슬래시 커맨드 하나 (`/plugin` 등). 어댑터가 세션 시작 때 통째로 준다. */
export type AcpCommand = {
	name: string,
	description: string,
	/**  인자 힌트 (있으면 입력창에 무엇을 더 쳐야 하는지 알려 준다). */
	hint: string | null,
};

/**  세션 설정 항목의 선택지 하나. */
export type AcpConfigChoice = {
	value: string,
	name: string,
	/**
	 *  어댑터가 주는 한 줄 설명 ("Standard behavior, prompts for dangerous
	 *  operations" 같은). 메뉴를 두 줄로 그릴 때 쓴다 — 우리가 지어내지 않는다.
	 */
	description: string | null,
};

/**
 *  세션 설정 항목 (모델·Effort·Fast mode·권한 모드·서브에이전트 …).
 * 
 *  목록을 우리가 하드코딩하지 않는 게 핵심이다 — 어댑터가 `session/new` 응답으로
 *  실제 선택지를 통째로 준다. Claude Code 가 모델을 추가하면 우리 코드를 고치지
 *  않아도 셀렉터에 나타난다.
 */
export type AcpConfigOption = {
	id: string,
	name: string,
	/**  `mode` · `model` · `thought_level` … (UI 정렬·아이콘용, 없을 수 있다). */
	category: string | null,
	/**  현재 값. select 면 value id, boolean 이면 `"true"`/`"false"`. */
	current: string | null,
	/**  select 의 선택지. boolean 항목은 빈 배열. */
	choices: AcpConfigChoice[],
	/**  true 면 토글, false 면 select. */
	is_boolean: boolean,
};

/**
 *  에이전트 화면이 뜨기 전에 무엇이 없는지 알려주기 위한 진단.
 * 
 *  실패를 "안 됨" 하나로 뭉치지 않는 이유: 사용자가 할 수 있는 조치가 각각
 *  다르다 — Node 설치 / Claude Code 로그인 / 어댑터 설치 버튼.
 */
export type AcpDiagnostics = {
	node_path: string | null,
	node_version: string | null,
	/**  Node 가 최소 버전 이상인가. */
	node_ok: boolean,
	node_min_major: number,
	/**  node 를 어디서 찾았는지 (로그인 셸에서 찾았다면 진단에 그대로 표시). */
	path_source: PathSource | null,
	npm_path: string | null,
	/**  어댑터가 구동할 Claude Code CLI. 없으면 핸드셰이크는 되도 프롬프트가 죽는다. */
	claude_path: string | null,
	/**
	 *  그 CLI 를 **어댑터가 들고 온 것**인가 (시스템 설치가 아니라).
	 * 
	 *  사용자에게 할 말이 달라진다: 딸려 온 것이면 따로 설치할 게 없고, 시스템
	 *  것이면 그쪽 버전이 오르내리는 것을 우리가 못 막는다.
	 */
	claude_bundled: boolean,
	adapter_version: string | null,
	adapter_expected: string,
	/**  설치돼 있고 고정 버전과 일치하는가. */
	adapter_ok: boolean,
	/**  전부 충족 — 에이전트를 띄울 수 있다. */
	ready: boolean,
};

/**  에이전트 화면이 받는 스트리밍 이벤트. */
export type AcpEvent = 
/**  답변 조각. */
{ kind: "chunk"; text: string } | 
/**
 *  사용자 발화 조각. 평소엔 우리가 이미 그린 것이라 무시되지만,
 *  `session/load` 의 **대화 재생**에서는 이걸로 지난 질문을 복원한다.
 */
{ kind: "user_chunk"; text: string } | 
/**  내부 추론 조각 (UI 는 기본 접어 둔다). */
{ kind: "thought"; text: string } | 
/**
 *  컨텍스트 사용량·누적 비용.
 * 
 *  토큰 수가 `u32` 인 건 specta 가 정밀도 손실을 이유로 64비트 정수 내보내기를
 *  막기 때문이다 — 컨텍스트 창은 백만 단위라 `u32` 로 충분하고, 넘치면
 *  포화시킨다(잘못된 작은 수보다 최대값이 덜 거짓말이다).
 */
{ kind: "usage"; used: number; size: number; cost_usd: number | null } | 
/**  도구 호출이 시작됐다. */
{ kind: "tool_call"; id: string; title: string; 
/**
 *  도구 이름 (`Bash` · `Read` · `Grep` …). 어댑터가 `_meta.claudeCode`
 *  로만 알려 준다 — 프로토콜 본문에는 없다.
 */
name: string | null; 
/**  한 줄 설명. Bash 는 모델이 적어 준 `description` 이 여기 온다. */
subtitle: string | null; 
/**  `read` · `edit` · `execute` … (아이콘 선택용). */
tool_kind: string; 
/**  `pending` · `in_progress` · `completed` · `failed`. */
status: string; 
/**  이 호출이 건드리는 파일들 (절대경로). */
locations: string[]; 
/**  도구에 들어간 것 (명령줄·인자). 카드의 `IN`. */
input: string | null; 
/**
 *  도구가 내놓은 것. 카드의 `OUT`. 시작 시점엔 대개 비어 있고
 *  `tool_update` 로 채워진다.
 */
output: string | null; 
/**
 *  편집 도구가 실어 온 파일 변경 — 예전엔 `"[diff]"` 문자열로 버렸다.
 *  무엇이 어떻게 바뀌는지는 이 화면의 핵심 정보라 구조 그대로 넘긴다.
 */
diffs: AcpToolDiff[] } | 
/**  진행 중인 도구 호출의 상태·제목이 바뀌었다. 없는 필드는 그대로 둔다. */
{ kind: "tool_update"; id: string; name: string | null; subtitle: string | null; title: string | null; status: string | null; 
/**  온 것만 실린다 — `None` 은 "안 왔다"이지 "비었다"가 아니다. */
input: string | null; output: string | null; 
/**  `None` 은 "content 가 안 왔다" — 이미 받은 diff 를 지우면 안 된다. */
diffs: AcpToolDiff[] | null } | 
/**  사용자 승인이 필요하다. 응답 전까지 에이전트는 멈춰 있다. */
{ kind: "permission"; request_id: string; title: string; tool_kind: string; 
/**  승인 대상 파일 — "무엇을 허용하는가"의 절반은 경로다. */
locations: string[]; options: AcpPermissionOption[]; 
/**
 *  승인 대상 변경 내용. 편집 승인에서 이것이 없으면 **무엇을 허용하는지
 *  못 본 채** 허용을 누르게 된다.
 */
diffs: AcpToolDiff[]; 
/**  도구에 들어갈 것 (실행 승인이면 명령줄) — diff 와 같은 이유로 싣는다. */
input: string | null } | 
/**
 *  세션 설정이 **에이전트 쪽에서** 바뀌었다.
 * 
 *  우리가 바꾼 것만이 아니다: 모델을 바꾸면 새 모델이 지원하지 않는 권한
 *  모드는 어댑터가 조용히 `default` 로 내린다(소스 확인). 이 이벤트를
 *  버리면 UI 는 "Auto" 라 적힌 채 실제로는 Manual 로 도는 상태가 된다 —
 *  사용자가 자동 승인될 거라 믿는 순간이라 안전 문제다.
 */
{ kind: "config_changed"; options: AcpConfigOption[] } | 
/**
 *  세션에 일어난 일 — 한도 초과·인증 실패·모델 폴백 …
 * 
 *  안 받으면 이런 것이 평범한 오류 문자열이나 **침묵**으로 온다. 특히 모델
 *  폴백(`warning`)은 알려 주지 않으면 알 길이 없다.
 */
{ kind: "failure"; 
/**  같은 사건의 갱신을 알아보는 표 — 같은 `id` 는 새 줄이 아니라 갱신이다. */
id: string; 
/**  `connection` · `access` · `limit` · `request` · `service` · `unknown`. */
category: string; 
/**  `warning` 또는 `error`. */
severity: string; title: string; details: string | null } | 
/**
 *  에이전트의 할 일 목록 (TodoWrite).
 * 
 *  **매번 전체가 온다** — 스펙이 "갱신할 때는 모든 항목을 현재 상태와 함께
 *  보내고, 클라이언트는 통째로 갈아 끼운다"고 못 박는다. 그래서 합치지 않고
 *  받은 것으로 대체한다.
 */
{ kind: "plan"; entries: AcpPlanEntry[] } | 
/**
 *  이번 턴에 에이전트가 **자기 입으로 신고한** 파일 변경 목록
 *  (어댑터 0.70.0 의 `agentFileChangeReport`).
 * 
 *  watcher·git diff 로 *추론*하는 것과 출처가 다르다: 턴이 끝나기 직전
 *  어댑터가 숨은 continuation 으로 "이번 턴에 바꾼 워크스페이스 파일을
 *  전부 신고하라"를 시키고, 그 답이 이 이벤트다. 명령·제너레이터·자식
 *  프로세스가 바꾼 것까지 포함하라고 지시하므로 watcher 가 놓치거나 다른
 *  창의 작업과 뒤섞이던 것을 교차 검증할 수 있다.
 * 
 *  **믿되 검증한다** — 모델이 적어 주는 목록이라 틀릴 수 있다. 그래서
 *  `complete`/`uncertainty` 를 그대로 실어 보낸다(모델이 스스로 "불완전할
 *  수 있다"고 말한 것을 우리가 숨기면 안 된다).
 */
{ kind: "file_change_report"; 
/**  우리가 프롬프트에 실어 보낸 요청 표 — 어느 턴의 보고인지 잇는다. */
request_id: string; 
/**  바뀐 파일들의 절대경로. `status != "reported"` 면 빈 목록이다. */
paths: string[]; 
/**  모델이 "이게 전부다"라고 선언했는가. */
complete: boolean; 
/**  어댑터가 한도(1024개·256KB)로 잘랐는가. */
truncated: boolean; 
/**  모델이 적어 준 불확실성 사유. */
uncertainty: string | null; 
/**
 *  보고를 못 받은 사유 — `cancelled`·`timeout`·`invalidOutput`·
 *  `notReported`·`providerError`. 받았으면 `None`.
 */
unavailable: string | null } | 
/**
 *  아직 UI 가 없는 업데이트 — 종류만 알려 준다.
 *  (필드 이름이 `kind` 가 아닌 건 내부 태그와 충돌하기 때문이다.)
 */
{ kind: "other"; update: string } | 
/**  턴 종료. */
{ kind: "done"; stop_reason: string } | 
/**  턴이 오류로 끝났다. */
{ kind: "failed"; message: string };

/**  프롬프트에 함께 보낼 이미지 하나 (붙여넣기·드롭). */
export type AcpImage = {
	/**  `image/png` 등. */
	mime_type: string,
	/**  data URI 접두사(`data:image/png;base64,`) 없이 **본문만**. */
	data_base64: string,
};

/**  권한 요청의 선택지 하나. */
export type AcpPermissionOption = {
	id: string,
	name: string,
	/**  `allow_once` · `allow_always` · `reject_once` … (버튼 강조에 쓴다). */
	option_kind: string,
};

/**  할 일 하나. */
export type AcpPlanEntry = {
	content: string,
	/**  `pending` · `in_progress` · `completed`. */
	status: string,
	/**  `high` · `medium` · `low`. */
	priority: string,
};

/**  한도 하나 (5시간 세션 · 주간 · 주간 Fable …). */
export type AcpRateLimit = {
	/**  어댑터가 준 종류 문자열 (`seven_day` 등) — 우리가 이름을 지어내지 않는다. */
	kind: string,
	/**  0.0~1.0. */
	utilization: number | null,
	/**  epoch 초. 표시용 문자열로 바꾸는 건 프런트 몫. */
	resets_at: number | null,
	/**
	 *  `/usage` 가 준 사람이 읽는 초기화 시각 ("Aug 16 at 4:59am (Asia/Seoul)").
	 *  epoch 보다 **덜 정확하지만 더 정직하다** — 우리가 시간대를 다시 계산하다
	 *  틀리느니 CLI 가 쓴 문장을 그대로 보여 준다.
	 */
	resets_text: string | null,
	/**  `allowed` · `allowed_warning` … (경고 색을 고르는 열쇠). */
	status: string | null,
};

/**  실행 중인 에이전트의 전체 상태 — 상대편 정보 + 세션 설정 항목. */
export type AcpSession = {
	agent: AcpAgentInfo,
	/**  슬래시 커맨드 목록 (`/plugin` 등) — 어댑터가 준 그대로. */
	commands: AcpCommand[],
	/**  현재 대화 세션 id — 목록에서 어느 것이 열려 있는지 표시하는 데 쓴다. */
	session_id: string | null,
	/**  현재 세션 제목 (에이전트가 붙여 준 것. 아직이면 `None`). */
	title: string | null,
	/**
	 *  모델 · Effort · Fast mode · 권한 모드 · 서브에이전트 …
	 *  **어댑터가 준 그대로**다 — 우리가 목록을 들고 있지 않는다.
	 */
	options: AcpConfigOption[],
};

/**
 *  세션·어댑터의 **생명주기**가 바뀌었다 (완성도 라운드 Phase 4). 프롬프트
 *  스트림(`AcpEvent`, 채널)은 턴이 도는 동안만 흐르므로 제목·설정·어댑터
 *  생사·대화 목록 변화는 실을 곳이 없었고, 화면은 4초마다 세 커맨드를 물었다.
 *  이 이벤트가 그 폴링을 대신한다 — 어느 창·탭이든 같은 프로젝트면 듣는다.
 */
export type AcpSessionChangeKind = "agent_ready" | "agent_gone" | "title" | "options" | "usage" | "created" | "selected" | "loaded" | "deleted";

export type AcpSessionChanged = {
	project_id: number,
	session_id: string | null,
	kind: AcpSessionChangeKind,
};

/**  과거 대화 하나 (에이전트가 보관한다 — 우리가 저장하지 않는다). */
export type AcpSessionSummary = {
	id: string,
	title: string | null,
	/**  ISO 8601 문자열 (어댑터가 주는 그대로 — 우리가 파싱해 다시 쓰지 않는다). */
	updated_at: string | null,
};

/**
 *  편집 도구가 만드는 파일 변경 하나 (`ToolCallContent::Diff`).
 * 
 *  원문(old/new) 그대로 넘기고 줄 비교는 프런트가 한다 — 여기서 통합 diff 를
 *  만들어 버리면 화면이 접기·색·통계를 다시 파싱해야 한다.
 */
export type AcpToolDiff = {
	/**  바뀌는 파일의 절대경로. */
	path: string,
	/**  바뀌기 전 내용. `None` 이면 새 파일. */
	old_text: string | null,
	/**  바뀐 뒤 내용. */
	new_text: string,
};

/**  마지막으로 본 사용량 한 벌. */
export type AcpUsage = {
	used: number,
	size: number,
	cost_usd: number | null,
	limits: AcpRateLimit[],
	/**
	 *  `/usage` 가 한도 뒤에 덧붙이는 "무엇이 사용량에 기여했나" 대목 — **원문 그대로**.
	 * 
	 *  구조를 뜯지 않는 이유: 컨텍스트 길이 경고·스킬·플러그인·MCP 서버처럼
	 *  항목이 계속 늘고 문구도 CLI 판올림마다 바뀐다. 표로 파싱해 두면 다음 판에
	 *  조용히 빈칸이 되는데, 원문을 그대로 보이면 무엇이 늘어도 그대로 보인다.
	 */
	detail: string | null,
};

export type AgentCount = {
	agent_id: string,
	entry_count: number,
	/**  `entry_count / total_entries`. `0.0` when no entries. */
	share: number | null,
};

export type AgentDetection = {
	agent_id: string,
	confidence: DetectConfidence,
	adapter_path_exists: boolean,
	adjacent_marker_exists: boolean,
};

export type AgentRef = {
	/**
	 *  e.g. `claude-code`, `cursor`, `antigravity`, `gemini-cli`, `pi`,
	 *  `windsurf`, `copilot`, `codex`, `aider`, `cline`, `zed`, `manual`
	 *  (자유 문자열 — 미지의 id 도 저장은 된다).
	 */
	id: string,
	/**  The model the agent ran on, e.g. `"Opus 4.8"` / `"Gemini 3 Pro"`. */
	version: string | null,
};

export type AgentSyncReport = {
	results: AgentSyncResult[],
};

export type AgentSyncResult = {
	id: string,
	/**  One of `inserted`, `updated`, `unchanged`, `removed`, `error`. */
	action: string,
	error: string | null,
	/**
	 *  blake3 hex of the bytes we own on disk after this sync. For
	 *  `Overwrite` adapters it's the file hash; for `ManagedBlock` adapters
	 *  it's the hash of the inner block content (between the markers). Used
	 *  by W4-PR4 to seed the drift comparator. `None` when the adapter was
	 *  removed / errored / left untouched without a file present.
	 */
	last_hash: string | null,
};

export type AgentsConfig = {
	/**
	 *  Subset of `config::KNOWN_AGENT_IDS` — `agents-md` + 도구별 어댑터
	 *  (claude-code/cursor/antigravity/gemini-cli/windsurf/copilot/aider/cline/zed).
	 */
	active: string[],
	/**
	 *  F1 — when on, the watcher reconciles the single active plan against each
	 *  newly-written journal entry via a background LLM call (`auto:<provider>`
	 *  attribution). Opt-in (default `false`): it triggers automatic, billable
	 *  LLM requests that send journal/plan text to the configured provider.
	 *  `#[serde(default)]` so pre-F1 `config.toml` files parse to `false`.
	 */
	auto_reconcile?: boolean,
	/**
	 *  PR-CI1 — when on, a hook-detected Claude Code session end (AgentExit)
	 *  triggers a background LLM summary of the session transcript into ONE
	 *  journal draft (skipped if the agent wrote its own entry). Opt-in
	 *  (default `false`): billable, and sends transcript excerpts to the
	 *  configured provider.
	 */
	auto_journal_draft?: boolean,
	/**
	 *  PR-CI3 — 규칙 크로스툴 번역 타깃 (`rules::TRANSLATE_TARGETS` 의 부분집합,
	 *  v1: "cursor"). 켜져 있으면 `.claude/rules/*.md` 저장 시 해당 도구의
	 *  규칙 파일로 병행 배포한다. `#[serde(default)]` 라 기존 config 는 빈
	 *  배열(off)로 파싱된다.
	 */
	rules_translate?: string[],
	/**
	 *  TK1 (template v6) — 마스터 템플릿 언어 (`ko` | `en`). 기존 config 는
	 *  default 로 `ko` 파싱. 변경은 다음 템플릿 시드/업그레이드부터 반영된다
	 *  (이미 시드된 `_template.md` 는 사용자 소유라 자동 교체하지 않음).
	 */
	template_language?: string,
};

export type AppError = {
	/**  snake_case 식별자 — `not_initialized`, `acp_not_running`, `unknown`. */
	code: string,
	/**  영어 원문. 없을 수 있다(코드만으로 충분한 경우). */
	detail: string | null,
};

export type AppInfo = {
	db_path: string,
	app_data_dir: string,
	secrets_store: string,
	version: string,
};

/**  탭을 옮길 수 있는 창 하나 (메뉴용). 이름은 프런트가 붙인다. */
export type AppWindowInfo = {
	label: string,
	/**  그 창에서 지금 보이는 탭의 프로젝트. 시작 탭이면 `None`. */
	active_project_id: number | null,
	tab_count: number,
};

/**
 *  Osaurus 라운드 Phase 0 (Decision 4) — 자동화의 전역 스위치.
 * 
 *  **전부 옵인, 기본 off.** `#[serde(default)]` 라 `[automation]` 섹션이 없는
 *  기존 `config.toml` 은 전부 꺼진 상태로 파싱된다. `.oculpm/automation/` 은
 *  신규 디렉터리라 기존 온디스크 스펙이 불변이고 `schema_version` 을 올리지
 *  않는다 (`auto_reconcile`·`auto_journal_draft` 선례).
 * 
 *  개별 정의 파일의 `enabled` 와는 **AND** 다 — 여기가 꺼져 있으면 켜 둔
 *  정의가 있어도 돌지 않는다.
 */
export type AutomationConfig = {
	/**  스케줄 집행 전역 스위치. */
	schedules?: boolean,
	/**  워처 자동화 전역 스위치. */
	watchers?: boolean,
	/**
	 *  한 워크데이에 자동화가 부를 수 있는 LLM 호출 상한 (폭주 가드).
	 *  `0` = 전면 정지. 드롭·스킵은 과금되지 않았으므로 세지 않는다.
	 */
	daily_run_budget?: number,
};

/**
 *  스케줄/워처 정의 하나. 스케줄·워처 전용 필드는 서로 `None` 이다.
 * 
 *  커맨드 경계를 그대로 건넌다 — 에디터가 편집하는 것이 곧 디스크에 쓰이는
 *  것이고, 그 사이에 매핑 표가 없다 (D1 의 "정의가 SSOT" 를 UI 까지 밀어붙인다).
 */
export type AutomationDef = {
	id: string,
	kind: AutomationKind,
	title: string,
	enabled: boolean,
	/**  `YYYY-MM-DD`. 시각은 주입받아 채운다 (호출부 규율 — 여기서 시계를 읽지 않는다). */
	created: string,
	updated: string,
	/**  `once|minutes|hourly|daily|weekly|monthly|yearly|cron`. */
	frequency: string | null,
	/**  `HH:MM` 또는 ISO 날짜시각(`once`). */
	at: string | null,
	weekday: string | null,
	day_of_month: number | null,
	month: number | null,
	day: number | null,
	/**  `minutes`/`hourly` 의 N. */
	every: number | null,
	/**  5필드 cron 식. */
	cron: string | null,
	/**  프로젝트 상대 경로. */
	watch: string | null,
	recursive: boolean | null,
	/**  `fast|balanced|patient|relaxed|deferred|extended`. */
	responsiveness: string | null,
	output: AutomationOutput,
	/**  본문 — 모델에게 그대로 가는 지시문. */
	instructions: string,
};

/**
 *  자동화의 두 축 — 스케줄은 시계에, 워처는 현실에 반응한다.
 * 
 *  직렬화 모양은 정의 파일의 `kind:` 값과 같다 (`schedule` / `watcher`) —
 *  디스크·바인딩·UI 가 한 어휘를 쓴다.
 */
export type AutomationKind = "schedule" | "watcher";

/**  자동화가 무엇을 남기는가. */
export type AutomationOutput = 
/**  규격 일지 1건. */
"journal" | 
/**  활성 플랜 글리프 갱신. */
"plan" | 
/**  산출물 없음 — 실행 원장의 메모로만 남는다 (아침 브리핑 카드 등). */
"none";

/**  실행 이력 한 줄 (`automation_runs`). */
export type AutomationRunDto = {
	/**
	 *  rowid 를 **문자열**로 넘긴다 — specta 는 정밀도 손실을 막으려 i64 를
	 *  거부하고, 프런트는 이 값을 목록 key 로만 쓴다 (산술 없음).
	 */
	id: string,
	automation_id: string,
	session_id: string,
	started_at: string,
	ended_at: string | null,
	status: string,
	/**  산출 일지의 프로젝트 상대 경로 — 클릭하면 일지 화면으로 점프한다. */
	journal_path: string | null,
	note: string | null,
};

/**  「지금 실행」의 결말. 프런트는 `status` 로 토스트 문구를 고른다. */
export type AutomationRunOutcome = {
	/**  `ran` | `dropped` | `skipped` | `failed` | `cancelled` */
	status: string,
	/**  기계가 읽는 사유 코드/원문 (영어). UI 언어를 넣지 않는다. */
	reason: string | null,
	journal_path: string | null,
};

/**  정의 + 런타임 상태 한 벌. 카드 하나가 필요로 하는 전부다. */
export type AutomationSummary = {
	def: AutomationDef,
	/**  파서 경고 (정의는 살아 있되 어긋난 것). 조용히 삼키지 않는다. */
	warnings: string[],
	/**  ISO8601 UTC. 스케줄만, 그리고 켜져 있을 때만. */
	next_run_at: string | null,
	last_run_at: string | null,
	last_status: string | null,
	/**  마지막 실행의 실패 사유 또는 빈도 해석 오류 코드. */
	last_error: string | null,
	/**  빈도를 해석하지 못한 이유 (`automation_bad_time` 등). 프런트가 i18n 키로. */
	spec_error: string | null,
};

/**
 *  Result of a git-history backfill (F5): one synthesised journal entry per
 *  commit. `skipped` counts commits already backfilled (idempotent re-runs).
 */
export type BackfillReport = {
	project_id: number,
	scanned: number,
	created: number,
	skipped: number,
};

/**
 *  `diff_binary_preview` 응답 — baseline 기준 이전/현재 바이트. 없는 쪽(신규의
 *  이전, 삭제의 현재)이나 16MB 초과 쪽은 `None` (프론트는 사이즈 카드만 표시).
 */
export type BinaryPreview = {
	old: BinarySide | null,
	new: BinarySide | null,
};

/**
 *  바이너리 diff 프리뷰의 한 쪽(이전/현재). 프론트가 `data:{mime};base64,…`
 *  URI 로 조립해 `<img>` 로 그린다.
 */
export type BinarySide = {
	mime: string,
	base64: string,
	size: number,
};

/**
 *  A group of changed files attributed to one journal entry (Dogfooding #3).
 *  `entry_path == None` is the trailing "미기록 변경" bucket for files no
 *  journal entry recorded.
 */
export type ChangeGroup = {
	entry_path: string | null,
	entry_title: string | null,
	entry_type: string | null,
	created_at: string | null,
	/**
	 *  `verified_by_user` of the entry — `None` for the untracked bucket. The
	 *  diff group header renders the same toggle the entry detail has, so a
	 *  review can be closed without leaving the diff (polish-round Phase 2).
	 */
	verified_by_user: boolean | null,
	plan_refs: ChangePlanRef[],
	files: string[],
};

/**
 *  One plan item linked (via the plan-log `journal_ref`) to a changed-file
 *  group's journal entry. Dogfooding #3 — surfaces "어떤 plan 에서" in the diff.
 */
export type ChangePlanRef = {
	plan_id: string,
	plan_title: string,
	item_title: string,
};

export type ChatEvent = { kind: "delta"; text: string } | { kind: "done" } | { kind: "error"; message: string };

export type ChatMessage = {
	id: number,
	conversation_id: number,
	role: string,
	content: string,
	provider: string | null,
	model: string | null,
	created_at: number,
};

export type ChatOptions = {
	model: string,
	temperature: number | null,
	max_tokens: number | null,
};

export type ChatResponse = {
	content: string,
	model: string,
	provider: string,
};

export type ChunkSearchResult = {
	chunk_id: number,
	file_path: string,
	start_line: number,
	end_line: number,
	content: string,
	distance: number | null,
};

export type ClaudeHooksStatus = {
	/**  3개 이벤트 전부에 우리 엔트리가 있다. */
	installed: boolean,
	/**  일부 이벤트에만 있다 (외부 편집으로 인한 드리프트 — 재설치 권장). */
	partial: boolean,
	/**  우리 것 아닌 훅 엔트리도 존재한다 (정보 표시용 — 건드리지 않음). */
	foreign_hooks: boolean,
	/**  `.claude/settings.local.json` 절대경로 (UI "파일 열기"용). */
	settings_path: string,
	/**
	 *  인박스 파일 현재 크기 (0 = 없음). 성장 관찰용. u32 saturating —
	 *  specta 가 u64(BigInt) 내보내기를 금지하고, 4GiB 넘는 인박스는 표시
	 *  정밀도가 무의미하다.
	 */
	inbox_bytes: number,
};

export type ClaudePluginStatus = {
	installed: boolean,
	/**  발견된 플러그인 디렉터리 (installed=true 일 때). */
	path: string | null,
};

export type CliCheckResult = {
	available: boolean,
	cli_name: string,
	path: string | null,
	version: string | null,
};

/**
 *  ⌘W 가 눌렸다 — **닫을 대상을 프런트가 고른다**.
 * 
 *  예전에는 Rust 가 곧장 탭을 닫았다. 그런데 화면 안에 또 닫을 것이 생겼다
 *  (Claude Code 의 세션 탭): 사용자는 브라우저처럼 "안쪽부터" 닫히기를 기대한다.
 *  무엇이 열려 있는지는 프런트만 아는 사실이라 판단도 그쪽이 한다.
 * 
 *  프런트가 안 듣고 있으면 ⌘W 는 아무 일도 하지 않는다 — 창을 닫는 길은
 *  ⇧⌘W(Close Window)에 그대로 남아 있고, 그쪽은 Rust 가 직접 처리한다.
 */
export type CloseIntent = {
	window: string,
	/**  프런트가 아무 것도 소비하지 않으면 닫을 탭. */
	tab: number | null,
};

/**
 *  `code_asset` 응답 — 이미지/PDF 바이트를 base64 + MIME 으로. 웹뷰는 임의 파일
 *  경로를 `<img src>` 로 직접 못 읽으므로, 프런트가 이걸 Blob 으로 되돌려 문다
 *  (docs 뷰어의 `docs_asset` 과 같은 계약).
 */
export type CodeAsset = {
	mime: string,
	base64: string,
	bytes: number,
};

/**  디렉터리 한 단계의 항목. 지연 로딩 트리가 폴더를 펼칠 때마다 이것만 받는다. */
export type CodeDirEntry = {
	name: string,
	relative_path: string,
	is_dir: boolean,
	/**
	 *  저장소가 무시하도록 정한 항목(gitignore · git exclude · global). 숨기지
	 *  않고 **흐리게** 그린다 — 디스크에 있는 것은 보이되 성질은 밝힌다.
	 */
	ignored: boolean,
};

/**  `code_dir` 응답. */
export type CodeDirListing = {
	entries: CodeDirEntry[],
	/**  [`MAX_DIR_ENTRIES`] 에 걸려 잘렸다 — UI 가 밝힌다. */
	truncated: boolean,
};

/**
 *  `code_read` 응답. `binary`/`too_large` 면 `content` 는 빈 문자열이고
 *  UI 는 "외부 에디터로 열기" 안내를 그린다.
 */
export type CodeFileContent = {
	content: string,
	/**  blake3(원본 바이트) hex — 저장 시 `base_hash` 로 되돌려 보내는 토큰. */
	hash: string,
	bytes: number,
	binary: boolean,
	too_large: boolean,
};

export type CodeGraph = {
	nodes: GraphNodeDto[],
	edges: GraphEdgeDto[],
};

/**
 *  `code_import` 결과. 건너뛴 것은 이유를 묶어 **개수만** 돌려준다 — 한 번에
 *  수백 개가 건너뛰어질 수 있어 목록을 그대로 토스트에 부으면 읽히지 않는다.
 */
export type CodeImportResult = {
	/**  새로 생긴 것들의 프로젝트 루트 기준 경로 (트리를 다시 읽고 열 자리). */
	imported: string[],
	/**  가져오지 못한 원본의 **이름**들 (경로가 아니라 이름 — 토스트용). */
	skipped: string[],
	/**  상한에 걸려 중간에 멈췄다. */
	truncated: boolean,
};

/**  파일/폴더를 만들거나 옮긴 결과. 프런트가 그대로 열거나 탭 경로를 갈아끼운다. */
export type CodePathResult = {
	/**  프로젝트 루트 기준 슬래시 경로 — `code_read`/`code_write` 인자와 같은 계약. */
	relative_path: string,
	is_dir: boolean,
};

/**
 *  `code_search_replace` 결과. 파일 단위 실패는 전체를 멈추지 않고 `errors` 로
 *  모은다 — 100개 파일 중 1개가 그 사이 바뀌었다고 99개를 포기할 이유가 없다.
 */
export type CodeReplaceOutcome = {
	files_changed: number,
	hits_replaced: number,
	errors: string[],
};

/**  한 매치만 바꿀 때의 좌표 — `code_search` 가 준 그 좌표를 그대로 되돌려 받는다. */
export type CodeReplaceTarget = {
	path: string,
	/**  1-based 줄 번호. */
	line: number,
	/**  줄 안 매치 시작 (UTF-16, 0-based). */
	col: number,
};

/**  한 파일의 매치 묶음. `path` 는 다른 code_* 커맨드와 같은 루트 기준 슬래시 경로. */
export type CodeSearchFile = {
	path: string,
	hits: CodeSearchHit[],
};

/**
 *  전역 검색의 매치 하나. `col`/`len` 은 **UTF-16 단위** — CodeMirror 의 문서
 *  오프셋과 JS 문자열 인덱스가 그 단위라, 여기서 변환해 주면 프런트는 그대로
 *  선택 범위로 쓴다 (바이트 오프셋을 넘기면 한글에서 어긋난다).
 */
export type CodeSearchHit = {
	/**  1-based 줄 번호. */
	line: number,
	/**  줄 안 매치 시작 (UTF-16, 0-based). */
	col: number,
	/**  매치 길이 (UTF-16). */
	len: number,
	/**  매치 주변 한 줄 미리보기 — 들여쓰기와 먼 앞부분은 잘라 낸다. */
	preview: string,
	/**  `preview` 안에서의 매치 시작 (UTF-16) — 목록의 하이라이트용. */
	preview_col: number,
};

/**  `code_search` 응답. */
export type CodeSearchResult = {
	files: CodeSearchFile[],
	total_hits: number,
	/**  [`MAX_SEARCH_HITS`] 상한에 걸려 잘렸다 — UI 가 "더 좁혀라" 로 알린다. */
	truncated: boolean,
};

/**  `code_tree` 응답. */
export type CodeTree = {
	nodes: CodeTreeNode[],
	file_count: number,
	/**  [`MAX_TREE_FILES`] 상한에 걸려 잘렸다 — UI 가 배지로 알린다. */
	truncated: boolean,
};

/**
 *  코드 트리 한 노드. `relative_path` 는 프로젝트 루트 기준 슬래시 경로 —
 *  그대로 `code_read`/`code_write` 인자로 쓴다 (docs 뷰어와 같은 계약).
 */
export type CodeTreeNode = {
	name: string,
	relative_path: string,
	is_dir: boolean,
	children: CodeTreeNode[],
};

/**
 *  `code_write` 결과 — 충돌은 오류가 아니라 정상 분기라 Err 로 보내지 않는다
 *  (프런트가 배너로 병합 선택지를 그려야 한다).
 */
export type CodeWriteOutcome = { kind: "saved"; hash: string } | { kind: "conflict"; disk_hash: string };

export type Conversation = {
	id: number,
	title: string,
	provider: string | null,
	model: string | null,
	project_id: number | null,
	created_at: number,
	updated_at: number,
	last_message_at: number | null,
};

export type ConversationAction = {
	id: number,
	conversation_id: number,
	message_index: number,
	status: string,
	applied_at: number,
};

/**
 *  Structured payload backing the Today screen. The frontend formats the
 *  numbers; we just join the underlying tables in a single round trip.
 * 
 *  `date_unix` is the local-day start (00:00) for which the brief was built.
 *  Callers can request any day, defaulting to "today" by passing `None`.
 * 
 *  Lite-W6 PR4: the changelog-derived fields were retired. The DTO shape
 *  is kept (with empty/zero placeholders) until the legacy DailyBrief
 *  view in TodayScreen is removed in a later PR; today's authoritative
 *  activity source is the journal entries rendered by TimelineView.
 */
export type DailyBrief = {
	date_unix: number,
	/**  Top 3 active goals — already ordered by priority then due_date. */
	focus_goals: Goal[],
	/**
	 *  Goals whose `updated_at` falls inside the requested day AND that are
	 *  marked completed. The "what did I finish" column.
	 */
	completed_today: Goal[],
};

/**  이 기계에서 쓸 수 있는 디버그 어댑터 한 줄 (안내용). */
export type DapAdapterInfo = {
	language_id: string,
	/**  찾았다면 그 절대경로. 못 찾았으면 `None`. */
	resolved: string | null,
	/**  미설치일 때 그대로 보여 줄 설치 방법 (자동 설치는 하지 않는다). */
	install_hint: string,
};

/**  중단점 하나의 확정 상태. */
export type DapBreakpoint = {
	/**  프로젝트 상대 경로. */
	path: string,
	/**  **1-based**. 어댑터가 다른 줄로 옮겼으면 옮긴 줄이 온다. */
	line: number,
	/**
	 *  어댑터가 실제로 걸 수 있다고 확인했나. `false` 면 그 줄에 코드가 없다는
	 *  뜻이라 **거터에 그 사실을 그린다** — 찍었는데 안 걸리는 이유를 모르면
	 *  사용자는 고장으로 읽는다.
	 */
	verified: boolean,
	/**  왜 못 거는지 (어댑터가 줄 때만). */
	message: string | null,
};

/**  어댑터가 확정한 중단점 상태 (옮겨졌거나 못 걸었거나). */
export type DapBreakpointsChanged = {
	project_id: number,
	breakpoints: DapBreakpoint[],
};

/**  한 파일의 중단점 줄들 (1-based). */
export type DapFileBreakpoints = {
	path: string,
	lines: number[],
};

/**  호출 스택 한 칸. */
export type DapFrame = {
	/**  어댑터가 준 프레임 id — `scopes` 요청의 키. `f64` 인 이유는 위와 같다. */
	id: number | null,
	name: string,
	/**
	 *  프로젝트 상대 경로. 밖(표준 라이브러리·런타임)이면 `None` — 지우지 않고
	 *  흐리게 그린다 (코드 트리가 gitignore 항목을 다루는 방식과 같다).
	 */
	path: string | null,
	/**  소스가 아예 없는 프레임(최적화·인라인)도 있다. */
	display_source: string | null,
	/**  **1-based**. */
	line: number,
	column: number,
};

/**  실행 구성 — 프런트가 그대로 채워 보낸다. */
export type DapLaunchRequest = {
	language_id: string,
	program: string,
	args: string[],
	stop_on_entry: boolean,
	cwd: string | null,
};

/**  디버그 콘솔 한 줄. */
export type DapOutput = {
	/**  `stdout` · `stderr` · `console` · `important`. */
	category: string,
	text: string,
};

/**  디버기의 표준 출력·오류 한 줄. */
export type DapOutputEmitted = {
	project_id: number,
	output: DapOutput,
};

/**  스코프(Locals · Globals · Registers …) 한 칸. */
export type DapScope = {
	name: string,
	variables_reference: number | null,
	/**  어댑터가 "읽는 데 비싸다" 고 표시한 것 (Registers 등) — 자동으로 펼치지 않는다. */
	expensive: boolean,
};

/**  세션 상태가 바뀌었다. 디버그 패널의 버튼 활성화가 전부 이걸로 파생된다. */
export type DapSessionChanged = {
	project_id: number,
	session: DapSessionInfo,
};

/**  세션 한 건의 겉모습 — 화면이 폴링 없이 이벤트로 받는다. */
export type DapSessionInfo = {
	state: DapState,
	/**  `rust` · `python` … 어떤 어댑터인지. */
	language_id: string,
	/**  디버그 중인 프로그램 (프로젝트 상대면 상대로). */
	program: string,
	/**  멈춘 이유 (`breakpoint` · `step` · `exception` …). Stopped 일 때만. */
	stopped_reason: string | null,
	/**
	 *  멈춘 스레드. 스택·변수 조회의 기준.
	 * 
	 *  **핸들은 `f64` 로 내보낸다.** DAP 의 id 는 JSON 숫자(=JS number)라 이쪽이
	 *  오히려 원본에 충실하고, specta 는 `i64` 를 IPC 로 내보내는 것을 막는다
	 *  (정밀도 손실 우려). 어댑터로 되돌릴 때만 정수로 캐스팅한다 — 실수로
	 *  직렬화하면 `682093.0` 이 되어 정수를 기대하는 어댑터가 거절한다.
	 */
	thread_id: number | null,
	/**  사람이 읽을 부가 설명 (미설치 안내·오류 사유). */
	detail: string | null,
};

/**  디버그 세션의 상태. 화면의 버튼 활성화가 전부 여기서 파생된다. */
export type DapState = 
/**  세션 없음. */
"idle" | 
/**  어댑터를 띄우고 initialize 협상 중. */
"starting" | 
/**  `initialized` 를 받아 중단점을 밀어 넣는 중. */
"configuring" | 
/**  프로그램이 돌고 있다. */
"running" | 
/**  중단점·스텝으로 멈췄다. 스택과 변수를 볼 수 있는 유일한 상태. */
"stopped" | 
/**  끝났다 (정상 종료·크래시·사용자 중단 모두). */
"ended";

/**
 *  변수 하나. 트리는 펼칠 때 읽는다 — 큰 구조체를 한 번에 다 읽으면 멈춘 순간
 *  앱이 굳는다 (코드 트리의 지연 로딩과 같은 원칙).
 */
export type DapVariable = {
	name: string,
	value: string,
	type_name: string | null,
	/**  0 이 아니면 펼칠 수 있다 — 그 값으로 자식을 묻는다. */
	variables_reference: number | null,
};

export type DbHealth = {
	sqlite_version: string,
	vec_version: string,
	schema_version: number,
	path: string,
	/**
	 *  데이터베이스 파일 크기(바이트) — 페이지 수 × 페이지 크기.
	 *  (f64: specta 는 u64 를 내보내지 않는다 — JS number 는 2^53 까지 정확하다.)
	 */
	db_bytes: number | null,
	/**  WAL 파일 크기(바이트). 체크포인트 전까지 커진다. */
	wal_bytes: number | null,
	/**  빈 페이지(바이트) — 삭제 뒤 남은 자리. [`Db::compact`] 가 되찾는다. */
	free_bytes: number | null,
	/**  큰 순서로 상위 표·인덱스 8개. */
	top_tables: DbTableSize[],
};

export type DbTableSize = {
	name: string,
	bytes: number | null,
};

/**  수확된 마커 한 건. */
export type DeferMarker = {
	/**  프로젝트 루트 기준 상대 경로 (`/` 구분자). */
	path: string,
	/**  1-based. */
	line: number,
	/**  `;` 앞 — 이 지름길의 천장(무엇을 미뤘는가). */
	ceiling: string,
	/**  `;` 뒤 — 재방문 트리거. 없으면 `None`. */
	trigger: string | null,
	/**  트리거가 없는 마커 — 조용히 썩는 것. 정렬에서 앞선다. */
	no_trigger: boolean,
};

/**  `defer_signals` 응답. 마커 0건이면 UI 가 카드를 그리지 않는다. */
export type DeferSignals = {
	/**  no_trigger 우선, 그다음 path·line 오름차순. */
	markers: DeferMarker[],
	/**  실제로 마커를 찾아본(스킵 제외) 파일 수. */
	files_scanned: number,
	/**  파일 2,000개·마커 200개 상한에 걸려 일부만 봤다는 표시. */
	truncated: boolean,
};

export type DesktopRegistrationStatus = {
	/**  설정 폴더가 존재한다 — Claude Desktop 설치 추정 근거. */
	installed: boolean,
	/**  이 프로젝트의 서버 엔트리가 등록되어 있다. */
	registered: boolean,
	config_path: string,
	/**  이 프로젝트가 쓰는 서버 키 (`oculpm-<폴더명>`). */
	server_key: string,
	/**  oculpm 아닌 서버 정의 수 (정보 표시용 — 건드리지 않음). */
	foreign_servers: number,
};

export type DetectConfidence = 
/**
 *  The adapter path itself exists — either we wrote it before, or a user
 *  (or another tool) is already aware of the adapter.
 */
"present" | 
/**
 *  An adjacent marker (`.cursor/`, `.claude/`, `.agent/`, `.gemini/`)
 *  exists but the adapter path doesn't — the user clearly uses this LLM
 *  even if our adapter isn't installed yet.
 */
"likely" | 
/**  No signal at all. */
"unknown";

export type DiffResult = {
	path: string,
	source: DiffSource,
};

export type DiffSource = 
/**  `git diff HEAD -- <path>` output. Empty `patch` = no diff. */
{ source: "git"; patch: string } | 
/**
 *  PR6.6 — snapshot vs disk unified-diff. Used when the git path can't
 *  serve a baseline: fresh repo (HEAD-less), non-git project, or git
 *  returned an empty patch but the file changed on disk after indexing.
 */
{ source: "snapshot"; patch: string } | 
/**
 *  이미지/기타 바이너리 파일 — 텍스트 diff 는 의미가 없어(깨진 문자 나열)
 *  파일 카드(이미지는 이전/현재 프리뷰 포함)로 렌더한다. 사이즈는 선택한
 *  baseline 기준 이전/현재 바이트 수; `None` 쪽은 존재하지 않음(신규/삭제).
 */
{ source: "binary"; is_image: boolean; old_size: number | null; new_size: number | null } | 
/**
 *  The file has neither a git baseline nor a captured snapshot. UI prompts
 *  the user to run a partial reindex first.
 */
{ source: "snapshots_unavailable" };

export type Difficulty = "superhigh" | "high" | "medium" | "low" | "verylow";

/**
 *  Wire wrapper so the frontend can express "set difficulty to None" vs
 *  "leave difficulty alone". Two-step Option unfolds to:
 *    - omitted / null → `None` (leave alone)
 *    - `{ value: null }` → `Some(None)` (clear)
 *    - `{ value: "high" }` → `Some(Some(High))` (set)
 */
export type DifficultyChange = {
	value: Difficulty | null,
};

export type DifficultyMix = {
	verylow: number,
	low: number,
	medium: number,
	high: number,
	superhigh: number,
	/**  Entries that didn't specify a difficulty in frontmatter. */
	null_count: number,
};

/**
 *  An attachment's bytes for inline rendering — base64 + MIME, assembled into a
 *  `data:` URI by the frontend (mirrors `DocsAsset`).
 */
export type DiscussionAsset = {
	mime: string,
	base64: string,
};

export type DiscussionAttachmentDto = {
	rel_path: string,
	kind: string,
};

export type DiscussionDetail = {
	discussion: DiscussionSummary,
	problem: string,
	background: string,
	options: DiscussionOptionDto[],
	log: DiscussionLogDto[],
	conclusion: string,
	next_steps: DiscussionNextStepDto[],
	attachments: DiscussionAttachmentDto[],
	resolution_plan_id: string | null,
	resolution_decided_at: string | null,
	tags: string[],
	/**  Non-fatal parse warnings — surfaced so the UI never fails silently. */
	warnings: string[],
};

export type DiscussionLogDto = {
	ts: string,
	author: string,
	body: string,
};

export type DiscussionNextStepDto = {
	step_id: string,
	title: string,
	done: boolean,
	order_idx: number,
};

export type DiscussionOptionDto = {
	option_id: string,
	title: string,
	body: string,
	order_idx: number,
};

export type DiscussionSummary = {
	discussion_id: string,
	title: string,
	status: string,
	owner: string,
	/**  First line of the problem statement, truncated — for the list preview. */
	problem_preview: string,
	option_count: number,
	next_step_count: number,
	resolution_plan_id: string | null,
	file_path: string,
	created_at: string,
	updated_at: string,
};

export type DispatchPrompt = {
	/**  조립된 프롬프트 파일 (프로젝트 상대 — `.oculpm/index/dispatch/…`). */
	file_rel: string,
	/**  터미널에 프리필할 한 줄 명령 (`claude "$(cat '…')"`). 실행은 사용자가. */
	command: string,
	/**
	 *  조립된 프롬프트 **본문**. 터미널에서 이미 코딩 에이전트가 돌고 있으면
	 *  프런트가 한 줄 명령 대신 이걸 그대로 붙여넣는다 — 돌던 세션을 끊고
	 *  `claude` 를 또 띄우는 대신, 하던 대화에 이어 붙이기 위해서다.
	 */
	prompt: string,
	item_title: string,
};

/**  `docs_asset` 응답 — 이미지 바이트를 base64 + MIME 으로. 프런트는 `data:` URI 로 조립한다. */
export type DocsAsset = {
	mime: string,
	base64: string,
};

/**  `docs_tree` 응답. `exists=false` 면 프로젝트에 `docs/` 폴더가 없다 (빈 상태 UI). */
export type DocsTree = {
	exists: boolean,
	nodes: DocsTreeNode[],
};

/**
 *  docs 트리 한 노드. `relative_path` 는 **프로젝트 루트 기준** 슬래시 경로
 *  (예: `docs/graph-upgrade/00-master-plan.md`) — 그대로 `docs_read`/`docs_asset` 인자로 쓴다.
 */
export type DocsTreeNode = {
	name: string,
	relative_path: string,
	is_dir: boolean,
	children: DocsTreeNode[],
};

/**
 *  A file where effort concentrated, annotated with its graph fan-out so the
 *  retro can say "time went into a high-fan-out core module" with evidence.
 */
export type EffortHotspot = {
	path: string,
	/**  Distinct journal entries that touched it in the range. */
	touch_count: number,
	/**
	 *  Files that (transitively) import it (`get_change_impact` reverse-BFS).
	 *  0 when the path isn't in the code index (deleted / non-source / not yet
	 *  indexed).
	 */
	impact_fan_out: number,
	is_hub: boolean,
};

export type EndedReason = "inactivity_timeout" | "app_quit" | "workday_boundary" | "manual" | "crash_recovered" | 
/**  W5 — session synthesized from migrated SQLite changelog entries. */
"synthetic_migrated" | 
/**
 *  PR-CI0 — external agent hook reported the session ended (Claude Code
 *  SessionEnd). Precise close, unlike the InactivityTimeout heuristic.
 */
"agent_exit";

export type EntityHit = {
	kind: EntityKind,
	id: string,
	title: string,
	/**  보조 문맥 — 일지: "워크데이 · 타입", 플랜 항목: 플랜 제목, 토의: status. */
	subtitle: string,
};

export type EntityKind = "journal" | "plan" | "plan_item" | "discussion";

/**
 *  One file's recorded diff for a journal entry. `patch` is a git-style unified
 *  diff (`a/ b/` headers) — never stored empty.
 */
export type EntryFileDiff = {
	path: string,
	patch: string,
};

/**
 *  User-facing filter for `list_entries`. Empty `types` means "all types".
 *  `search` matches against `title`, `slug`, `body_markdown`, and any tag
 *  in `oculpm_journal_tags` (case-insensitive for ASCII; substring for
 *  other scripts including Hangul).
 */
export type EntryFilters = {
	types: EntryType[],
	verified_only: boolean,
	/**
	 *  Reserved for W4 (LayerComparison). PR2 wires the column path but
	 *  `mismatch_only=true` returns no rows because no entry has been
	 *  flagged yet.
	 */
	mismatch_only: boolean,
	/**  `checkbox == Some(false)` OR `status != "done"`. */
	unfinished_only: boolean,
	search: string | null,
	/**  W5-PR6 — agent_id filter. Empty = no constraint (all agents). */
	agents?: string[],
	/**
	 *  W5-PR6 — difficulty filter. Empty = no constraint. Note the cache
	 *  column is nullable ("미지정"); difficulty filter therefore *cannot*
	 *  match the null bucket — that's a separate W6 toggle.
	 */
	difficulties?: Difficulty[],
};

export type EntryStatus = "planned" | "in_progress" | "done" | "abandoned";

export type EntryType = "bug" | "feature" | "error" | "refactor" | "chore";

/**  `## 기록` 표의 한 행. */
export type EvalRecord = {
	/**  `YYYY-MM-DD`. */
	date: string,
	suite: string,
	passed: number,
	total: number,
	memo: string,
};

/**
 *  `eval_signals` 응답. `EVALS.md` 자체가 없으면 커맨드가 `None` 을 돌려
 *  UI 가 섹션을 그리지 않는다.
 */
export type EvalSignals = {
	/**  날짜 오름차순 (동일 날짜는 문서 순서 유지), 최근 200건. */
	records: EvalRecord[],
	/**  등장한 스위트명 (등장 순서). */
	suites: string[],
};

export type FileChangeEvent = {
	ts: string,
	session_id: string,
	op: FileOp,
	path: string,
	hash_before: string | null,
	hash_after: string | null,
	/**
	 *  u32 — caps at 4 GB per file. Larger files skip hashing anyway
	 *  (`tags: ["large-file-hash-skipped"]`) so the value will be clamped.
	 */
	bytes: number,
};

/**
 *  v2 U7 (docs/20260706_v2/02-features-spec.md §2) — 팔레트 "go to anything"
 *  히트 한 건. `id` 는 kind 별 라우팅 키: journal=relative_path,
 *  plan=plan_id, plan_item="plan_id#item_id", discussion=discussion_id.
 *  코드 화면 — "이 파일을 고친 일지" 역조회 한 줄
 *  (`oculpm_journal_files` × `oculpm_journal`). 에디터 브레드크럼의 일지 칩이
 *  소비한다: 에이전트가 이 파일에 무슨 일을 했는지가 편집 중에 보인다.
 */
export type FileJournalEntry = {
	/**  일지 캐시 키 (`20260823/Bugs/….md`) — 그대로 일지 화면 점프에 쓴다. */
	journal_path: string,
	title: string,
	/**  bug | feature | error | refactor | chore. */
	entry_type: string,
	agent_id: string,
	/**  RFC3339 (frontmatter created_at). */
	created_at: string,
	/**  그 일지에서 이 파일에 한 일 — create | update | delete | rename | correct. */
	op: string,
};

export type FileOp = "create" | "update" | "delete" | "rename" | "correct";

export type FileTouched = {
	path: string,
	op: FileOp,
	bytes_added: number | null,
	bytes_removed: number | null,
	rename_from: string | null,
};

/**  발동 통계 창 조회 결과. */
export type FiringOverview = {
	stats: FiringStat[],
	/**  조회 창 (workday, 포함 양끝). */
	since: string,
	until: string,
	/**  창 안에서 발동이 관측된 세션 수. */
	sessions: number,
	/**  세션 1건당 규칙 주입 바이트 (컨텍스트 예산 바의 값). */
	bytes_per_session: number,
	/**  마지막 스캔 시각 (unix). None = 한 번도 안 돌았다. */
	last_scan_at: number | null,
};

/**  한 번의 증분 스캔 결과. */
export type FiringScanReport = {
	/**  이번에 새로 읽은 파일 수 (변화 없는 파일은 세지 않는다). */
	files_scanned: number,
	/**  이번에 새로 적재한 집계 행 수. */
	rows_written: number,
	/**  transcript 폴더를 못 찾았다 (Claude Code 사용 이력 없음 등). */
	no_transcripts: boolean,
	/**  false 면 예산이 동나 남은 분량이 있다 — 다시 부르면 이어 간다. */
	complete: boolean,
};

/**  프런트가 그대로 그리는 발동 통계 1행. */
export type FiringStat = {
	/**  `rule` | `skill`. */
	kind: string,
	/**  규칙 절대경로 · 스킬 이름 (조회 키). */
	key: string,
	/**  표시용 축약 라벨. */
	label: string,
	/**  창 안의 발동 총 횟수. */
	count: number,
	/**
	 *  창 안의 주입 바이트 합 (스킬은 0). specta 가 u64 노출을 막으므로
	 *  포화 변환한 u32 — 실측 규모(세션당 ~90KB)에서 도달할 수 없는 상한이다.
	 */
	bytes: number,
	/**  발동한 서로 다른 세션 수. */
	sessions: number,
	/**  가장 최근 발동 workday. */
	last_workday: string | null,
};

export type GeneratedSummary = {
	style: SummaryStyle,
	markdown: string,
	entry_count: number,
	used_llm: boolean,
	/**  LLM 폴백 사유 등 사용자에게 알릴 한 줄 (없으면 None). */
	note: string | null,
};

/**
 *  A single uncommitted change from `git status`. `op` is one of `"A"` / `"M"` /
 *  `"D"` so it lines up directly with the frontend `ChangeOp` union used by the
 *  변경 diff 화면. Renames/copies report the *new* path as an add.
 */
export type GitChange = {
	path: string,
	op: string,
};

export type GitCommit = {
	sha: string,
	short_sha: string,
	author_name: string,
	author_email: string,
	/**  Unix timestamp in seconds (author date). */
	timestamp: number,
	subject: string,
};

export type GitConfig = {
	forbid_journal_for_paths: string[],
	auto_redact_patterns: string[],
};

/**
 *  One commit in the graph view (Today git graph). Carries `parents` for lane
 *  routing and `refs` (branch/tag/HEAD decorations) so the UI can badge tips.
 */
export type GitGraphCommit = {
	sha: string,
	short_sha: string,
	parents: string[],
	author_name: string,
	/**  Unix timestamp in seconds (author date). */
	timestamp: number,
	subject: string,
	/**
	 *  Ref names pointing here (e.g. `main`, `origin/main`, a tag), HEAD-/tag-
	 *  prefixes stripped.
	 */
	refs: string[],
};

/**
 *  Lite-W6 PR5 — slim wrapper for the TitleBar mini git chip (UI consumer
 *  arrives in PR7). Returns just the branch + the count of `git status
 *  --porcelain` lines (staged + unstaged + untracked).
 */
export type GitHeadStatusBrief = {
	is_git_repo: boolean,
	/**  `None` when the repo is in detached-HEAD state or there is no repo. */
	head_branch: string | null,
	/**  Count of `--porcelain` lines. Capped at u32::MAX in practice. */
	uncommitted: number,
};

/**  에디터 거터에 그릴 한 덩어리의 변경. 줄 번호는 **1-based, 현재 버퍼 기준**. */
export type GitLineChange = {
	/**  첫 줄 (포함). */
	start_line: number,
	/**
	 *  마지막 줄 (포함). `deleted` 는 start_line == end_line 이고, 그 줄
	 *  **다음에** 무언가 지워졌다는 뜻이다 (지워진 줄은 화면에 없으므로).
	 */
	end_line: number,
	kind: GitLineChangeKind,
};

export type GitLineChangeKind = "added" | "modified" | "deleted";

export type GitRemote = {
	name: string,
	url: string,
	/**  e.g. "github.com" — derived from the URL. */
	host: string | null,
	owner: string | null,
	repo: string | null,
};

export type GitRepoStatus = {
	is_git_repo: boolean,
	head_branch: string | null,
	remotes: GitRemote[],
};

/**  glob 하나의 매칭 결과. */
export type GlobMatch = {
	glob: string,
	/**  이 프로젝트에서 매칭된 파일 수 (상한까지 셈). */
	files: number,
	/**  glob 을 해석하지 못했다 — 판정 불가라 dead 로 부르지 않는다. */
	unparsed: boolean,
};

