export type JournalEntry = {
	/**  `<workday>/<Category>/<file>.md` — relative to `.oculpm/journal/`. */
	relative_path: string,
	frontmatter: JournalFrontmatter,
	/**  First non-blank line after frontmatter, with the `[ ]`/`[x]` prefix stripped. */
	title: string,
	/**  `None` when first line lacks a checkbox; `Some(true)` for `[x]`, `Some(false)` for `[ ]`. */
	checkbox: boolean | null,
	body_markdown: string,
	/**
	 *  u32 (not u64) for specta BigInt-export compatibility — see
	 *  docs/2026521/Errors/2026-05-21-specta-bigint-export.md. Caps at 4 GB
	 *  which no realistic journal entry will hit.
	 */
	byte_size: number,
	mtime: string,
	/**
	 *  False when the YAML frontmatter failed to parse (the row is still cached
	 *  as a synthesized chore). Drives a ⚠ reliability badge (F7a).
	 */
	parse_ok: boolean,
	/**  Non-fatal parse warnings (missing tz offset, agent-as-string, bad op, …). */
	parse_warnings: string[],
};

export type JournalEntrySummary = {
	relative_path: string,
	workday: string,
	type: EntryType,
	slug: string,
	status: EntryStatus,
	difficulty: Difficulty | null,
	title: string,
	checkbox: boolean | null,
	session_id: string,
	agent_id: string,
	/**
	 *  The model the agent reported (frontmatter `agent.version`), e.g.
	 *  `"Opus 4.8"` / `"Gemini 3 Pro"`. `None` when not reported.
	 */
	agent_version: string | null,
	verified_by_user: boolean,
	created_at: string,
	updated_at: string | null,
	tags: string[],
	files_count: number,
	parse_ok: boolean,
	parse_warnings: string[],
};

export type JournalFrontmatter = {
	schema_version: number,
	type: EntryType,
	slug: string,
	status: EntryStatus,
	difficulty: Difficulty | null,
	created_at: string,
	updated_at: string | null,
	session_id: string,
	agent: AgentRef,
	/**  Two-letter ISO 639-1, e.g. `ko` or `en`. */
	language: string,
	verified_by_user: boolean,
	files_touched: FileTouched[],
	related: RelatedRef[],
	tags: string[],
};

/**
 *  일지 없이 끝난 세션 1건. `ts` 는 훅이 기록한 UTC ISO 문자열 그대로 —
 *  로컬 시각 변환은 UI 몫이다.
 */
export type JournalMissingSignal = {
	ts: string,
	session_id: string,
};

/**
 *  The most recent commit's metadata + the files it touched. Powers the 변경
 *  diff 화면's "직전 커밋" baseline, shown when the working tree is clean so the
 *  screen isn't empty after a coding agent commits its work.
 */
export type LastCommitChanges = {
	sha: string,
	short_sha: string,
	subject: string,
	changes: GitChange[],
};

/**
 *  W4-PR5 — diff between the watcher's ndjson (index, ground truth) and
 *  the union of `files_touched[].path` from journal entries that name a
 *  given `session_id`. See `docs/major_update/oculpm/W4/PR5-compare-layers.md`.
 */
export type LayerComparison = {
	session_id: string,
	workday: string,
	/**
	 *  Distinct project-relative paths from `file_changes.ndjson` for this
	 *  session, after stripping forbidden + `**redacted/sensitive**:*` paths.
	 */
	index_files: string[],
	/**
	 *  Union of `files_touched[].path` across every journal entry that names
	 *  this session, after the same forbidden / redacted strip.
	 */
	journal_files: string[],
	matched: string[],
	/**
	 *  In the index but not the journal **of this exact session**.
	 * 
	 *  Only meaningful when the agent stamps the watcher's own `session_id`
	 *  scheme. Agents that mint their own (`manual-20260820-205400`) make this
	 *  equal to `index_files` — use [`Self::unrecorded`] to judge honesty.
	 */
	only_in_index: string[],
	/**  In the journal but not the index — likely *hallucinated path*. */
	only_in_journal: string[],
	mismatch_severity: Severity,
	/**
	 *  `|matched| / |union|`. `1.0` when both sets are empty (treated as
	 *  trivially in sync — no activity, nothing to disagree on).
	 */
	jaccard_index: number | null,
	/**
	 *  Changed in this session and named by **no journal entry anywhere in
	 *  the workday** — the honest "미기록" set, immune to session-id dialect
	 *  mismatches. This is what 정직성 감사 renders.
	 */
	unrecorded: string[],
	/**
	 *  Severity of [`Self::unrecorded`], bucketed from the share of this
	 *  session's changed files that *are* covered by some journal entry.
	 *  `Ok` when the session changed nothing.
	 */
	unrecorded_severity: Severity,
};

export type LocalDiffReindexReport = {
	indexed: string[],
	skipped: ReindexSkip[],
	elapsed_ms: number,
	embeddings_updated: number,
	ast_updated: number,
};

export type LockStateView = "healthy" | "held_by_other" | "recovered" | "uninitialized";

export type LspCodeAction = {
	/**
	 *  마지막 목록에서의 자리. 적용할 때 이 번호로 되짚는다 — 서버별 `data` 가
	 *  붙은 원본 객체를 프런트로 왕복시키지 않기 위해서다.
	 */
	index: number,
	title: string,
	/**  `quickfix` · `refactor` · `source` … 없을 수도 있다. */
	kind: string | null,
	/**  서버가 "이걸 먼저" 라고 표시한 것 (대개 가장 그럴듯한 fix). */
	preferred: boolean,
};

export type LspCompletionItem = {
	label: string,
	/**  타입/시그니처 — 목록 오른쪽에 흐리게. */
	detail: string | null,
	/**  `function` · `variable` · `struct` … CM6 아이콘으로 매핑된다. */
	kind: string | null,
	/**  라벨과 실제로 넣을 텍스트가 다를 때만 (`insertText`/`textEdit`). */
	insert_text: string | null,
	/**  정렬용 — 서버가 준 순서를 존중한다. CM6 가 자체 정렬하지 않게 한다. */
	sort_text: string | null,
};

export type LspDiagnostic = {
	/**  0-based, LSP 원본 그대로 (UTF-16 코드 유닛). */
	start_line: number,
	start_character: number,
	end_line: number,
	end_character: number,
	severity: LspSeverity,
	message: string,
	/**  `rustc` · `clippy` · `ts` 등. 어느 도구가 한 말인지 밝힌다. */
	source: string | null,
};

/**
 *  진단이 갱신됐다. 창을 가리지 않고 전역으로 나가고, 코드 화면이
 *  `project_id` + `path` 로 거른다 (OculpmFileChanged 와 같은 방식).
 */
export type LspDiagnosticsPublished = {
	project_id: number,
	/**  프로젝트 상대 경로. */
	path: string,
	diagnostics: LspDiagnostic[],
};

/**
 *  포맷팅 — **디스크가 아니라 넘겨받은 텍스트에** 적용해 돌려준다.
 * 
 *  이름 바꾸기·코드 액션과 정반대의 선택이다. 그것들은 열려 있지 않은 파일까지
 *  고치므로 디스크에 적용하고 미저장 버퍼를 금지했다. 포맷팅은 **지금 편집 중인
 *  한 파일**이 대상이라, 저장을 강요하는 대신 버퍼를 그대로 다듬어 돌려주는
 *  것이 맞다 (저장 시 포맷도 이 위에 얹힌다).
 * 
 *  호출 전에 프런트가 `lsp_change` 로 현재 버퍼를 밀어 넣어야 한다 — 서버가
 *  아는 문서와 여기 넘긴 `text` 가 다르면 편집 오프셋이 어긋난다.
 *  바뀐 것이 없으면 `None`(서버가 빈 편집을 준 경우 포함).
 *  ⇧⌥F 의 선택 범위 (0-based UTF-16 — 다른 LSP 좌표와 같은 규약).
 */
export type LspFormatRange = {
	start_line: number,
	start_character: number,
	end_line: number,
	end_character: number,
};

export type LspHover = {
	/**  마크다운 원문. 프런트가 코드 블록과 산문으로 갈라 렌더한다. */
	contents: string,
};

export type LspLocation = {
	/**
	 *  프로젝트 상대 경로. 프로젝트 **밖**(의존성 소스·표준 라이브러리)이면
	 *  `None` — 코드 화면이 열 수 없는 파일이다. 조용히 아무 일도 안 하는
	 *  대신 어디로 가려 했는지 말해 주기 위해 `display` 를 함께 준다.
	 */
	path: string | null,
	/**  사람에게 보여줄 이름 (프로젝트 안이면 상대 경로, 밖이면 파일명). */
	display: string,
	/**  0-based, LSP 원본 그대로. */
	line: number,
	character: number,
};

/**  시그니처 라벨 안에서 인자 하나가 차지하는 구간. */
export type LspParamSpan = {
	/**  `label` 문자열 안의 UTF-16 오프셋 [start, end). */
	start: number,
	end: number,
};

/**  파일 하나에 모인 참조들. 목록이 파일 단위로 접히도록 서버 응답을 묶는다. */
