export type ReindexSkip = {
	path: string,
	reason: ReindexSkipReason,
};

/**
 *  Per-path outcome surfaced to the UI. Skip reasons let the caller render a
 *  "(skipped: too large)" badge next to the path without re-running
 *  `walk_text_files` filters.
 */
export type ReindexSkipReason = { kind: "not_found" } | { kind: "read_failed"; error: string } | { kind: "upsert_failed"; error: string } | 
/**  minified/생성 파일 — 한 줄이 `indexer::MAX_LINE_BYTES` 를 넘는다. */
{ kind: "generated" };

export type RelatedRef = {
	/**  Path relative to `.oculpm/journal/` (e.g. `20260522/Bugs/2050_bug_X.md`). */
	ref: string,
	/**  One of `blocks`, `blocked_by`, `followup`, `duplicate`. */
	kind: string,
};

/**
 *  A file touched by 2+ error/bug entries in the range — a recurring trouble
 *  spot.
 */
export type RepeatedFile = {
	path: string,
	/**  Number of distinct error/bug entries that touched it. */
	count: number,
};

/**  A friction unit — an error/bug journal entry. */
export type ResistanceItem = {
	/**  Raw frontmatter type: `error` | `bug`. */
	kind: string,
	title: string,
	status: string,
	workday: string,
};

/**
 *  F4 — one cached retrospective for a workday range. `signature` is a hash of
 *  the deterministic signals; when it diverges from the current signals the
 *  frontend marks the cached narrative stale. Mirrors `project_overviews`.
 */
export type RetroInsight = {
	project_id: number,
	/**  "YYYYMMDD..YYYYMMDD" (inclusive workday range). */
	range_key: string,
	signature: string,
	retro_md: string,
	generated_at: number,
	generated_by_model: string | null,
};

/**
 *  The deterministic signal set the retro is grounded in. Returned to the UI
 *  directly *and* fed to the LLM. `signature` hashes everything but itself, so
 *  the frontend can compare it to a cached retro's signature to show staleness.
 */
export type RetroSignals = {
	/**  Workday "YYYYMMDD". */
	since: string,
	until: string,
	/**  "since..until". */
	range_key: string,
	signature: string,
	total_entries: number,
	shipped: ShippedItem[],
	resistance: ResistanceItem[],
	repeated_files: RepeatedFile[],
	effort_hotspots: EffortHotspot[],
	agent_breakdown: AgentCount[],
	difficulty_mix: DifficultyMix,
};

export type Role = "system" | "user" | "assistant";

/**  `rules_save_with_backup` 응답 — 저장 결과 + 되돌릴 백업 경로. */
export type RuleBackupOutcome = {
	entry: RuleEntry,
	mirror: MirrorWriteResult | null,
	/**  원본을 남긴 절대 경로 — 토스트가 그대로 보여 준다. */
	backup_path: string,
};

/**  결정적 규칙 후보 — 한 코드 영역의 반복 실패 클러스터. */
export type RuleCandidate = {
	/**  억제/재조회 키 (`area:<영역>`). */
	key: string,
	/**  공유 디렉터리 영역 (예: `src-tauri/src/oculpm`). */
	area: string,
	/**  클러스터의 실패(error/bug) 일지 수. */
	entry_count: number,
	/**  등장한 종류 (정렬: `bug`, `error`). */
	kinds: string[],
	/**  표본 제목 (최신순, 최대 4). */
	sample_titles: string[],
	/**  증거 일지의 캐시 상대경로 (최신순 — 초안 생성이 본문을 읽는다). */
	entry_rels: string[],
	/**  결정적 paths 제안 (`<area>/**`) — LLM 이 다듬되 폴백으로도 쓴다. */
	suggested_paths: string[],
	/**  가장 최근 실패 workday. */
	last_workday: string,
};

/**  `rules_read` 응답. */
export type RuleDetail = {
	entry: RuleEntry,
	content: string,
	/**  절대 경로 — 외부 에디터로 열 때 사용. */
	abs_path: string,
};

/**
 *  LLM 이 만든 규칙 초안. `content` 가 저장용 완성본 — 프런트는 슬러그만
 *  바꿔서 `rules_save(".claude/rules/<slug>.md", content, create=true)` 를
 *  부른다 (승인 없이는 어떤 파일도 쓰이지 않는다).
 */
export type RuleDraft = {
	candidate_key: string,
	slug: string,
	title: string,
	paths: string[],
	body_markdown: string,
	/**  frontmatter(paths) + promoted-from 마커 + 본문의 저장용 완성본. */
	content: string,
	/**  제안 저장 위치 (`.claude/rules/<slug>.md`). */
	rel_path: string,
};

/**  목록의 한 줄. `(scope, rel_path)` 가 조작 키다. */
export type RuleEntry = {
	scope: RuleScope,
	kind: RuleKind,
	/**  스코프 루트 상대 경로 (`CLAUDE.md`, `.claude/rules/api/validation.md` …). */
	rel_path: string,
	/**  표시명 — ClaudeMd 는 파일명, Rule 은 rules/ 이하 스템 (`api/validation`). */
	name: string,
	/**  본문 첫 H1 텍스트 (없으면 빈 문자열) — 목록 부제용. */
	title: string,
	/**  ClaudeMd 슬롯 전용 — 파일이 아직 없으면 false ("만들기" 어포던스). */
	exists: boolean,
	/**  frontmatter `paths` (없으면 빈 배열 = 항상 로드). */
	paths: string[],
	bytes: number,
	mirror: MirrorState,
};

export type RuleKind = 
/**  CLAUDE.md 계열 고정 슬롯 (항상 로드되는 메모리 파일). */
"claude_md" | 
/**  `.claude/rules/**\/*.md` 규칙 파일. */
"rule";

/**  `rules_save` 응답 — 저장된 엔트리 + (옵인 시) 미러 결과. */
export type RuleSaveOutcome = {
	entry: RuleEntry,
	mirror: MirrorWriteResult | null,
};

export type RuleScope = 
/**  프로젝트 루트 기준 (`<project>/CLAUDE.md`, `<project>/.claude/rules/…`). */
"project" | 
/**  홈 디렉터리 기준 (`~/.claude/CLAUDE.md`, `~/.claude/rules/…`). */
"global";

/**  규칙 하나의 감사 결과. */
export type RuleScopeFinding = {
	scope: RuleScope,
	rel_path: string,
	/**  발동 원장 키와 같은 절대경로 — 프런트가 주입 실측치와 잇는다. */
	abs_path: string,
	name: string,
	/**  규칙 본문 바이트 (되찾을 수 있는 양의 근거). */
	bytes: number,
	globs: GlobMatch[],
	/**  매칭 0개인 glob (무관 확정). */
	dead_globs: string[],
	/**  남길 glob — 축소 제안이 그대로 쓴다. */
	live_globs: string[],
};

/**  `rules_list` 응답 — 전 스코프를 한 번에 (스킬 overview 패턴). */
export type RulesOverview = {
	/**  고정 슬롯 (프로젝트 3 + 전역 1, exists=false 포함). */
	claude_md: RuleEntry[],
	project_rules: RuleEntry[],
	global_rules: RuleEntry[],
	/**  절대 경로 — 빈 상태 안내용. */
	project_rules_dir: string,
	global_rules_dir: string,
	/**  `config.agents.rules_translate` 에 "cursor" 가 있는가. */
	cursor_translate: boolean,
};

export type Session = {
	/**  `YYYYMMDD-NNN`. */
	id: string,
	started_at: string,
	ended_at: string | null,
	ended_reason: EndedReason | null,
	/**
	 *  u32 — caps at ~49 days of continuous active time. A single session
	 *  will never approach this.
	 */
	active_window_ms: number,
	file_event_count: number,
	files_unique: number,
	git_head_at_start: string | null,
	git_head_at_end: string | null,
	agent_label_guess: string | null,
	/**  Paths relative to `.oculpm/journal/<workday>/`. */
	linked_journal_entries: string[],
};

export type SessionConfig = {
	inactivity_timeout_minutes: number,
	/**
	 *  W4 dogfooding fix — minutes within which new activity after an
	 *  InactivityTimeout finalize will REOPEN the most recent
	 *  inactivity-closed session instead of starting a new one. Bounded by
	 *  today's workday (we never resurrect sessions across the workday
	 *  boundary). `0` disables resume entirely. Defaults to 15 minutes.
	 */
	session_resume_grace_minutes?: number,
};

export type SessionDailyAgg = {
	workday: string,
	session_count: number,
	total_active_seconds: number,
	files_unique: number,
	journal_entry_count: number,
	/**
	 *  `journal_entry_count / sessions_with_file_events`. `0.0` when no
	 *  sessions have file events (avoids NaN). UI shows as percentage.
	 */
	narrative_rate: number | null,
};

export type SessionUnrecorded = {
	session_id: string,
	/**  이 세션이 바꿨는데 그날 어떤 일지도 적지 않은 파일 — [`LayerComparison::unrecorded`] 와 같은 판정. */
	unrecorded: string[],
	unrecorded_severity: Severity,
};

/**
 *  설정이 바뀌었다 — **모든 창**이 다시 읽는다.
 * 
 *  창이 여럿이고(크롬식 탭) 트레이 팝오버는 앱 시작 때 한 번 만들어져
 *  세션 내내 살아 있다. 각 창의 `SettingsProvider` 는 마운트 때 한 번만
 *  읽으므로, 이 이벤트가 없으면 한 창에서 테마·언어를 바꿔도 나머지 창과
 *  상단바(트레이 팝오버)는 예전 값을 그대로 그린다.
 */
export type SettingsChanged = {
	keys: string[],
};

export type Severity = "ok" | "warning" | "critical";

/**  설치 상태. UI 가 "설치 / 제거" 버튼 상태를 정하는 데 쓴다. */
export type ShellIntegrationStatus = {
	/**  `$SHELL` 로 판정한 셸 종류. */
	shell: ShellKind,
	/**  rc 에 우리 관리 블록이 있다. */
	installed: boolean,
	/**  rc 절대경로 (지원 셸이 아니면 빈 문자열). */
	rc_path: string,
	/**  앱이 심는 스크립트 절대경로 (지원 셸이 아니면 빈 문자열). */
	script_path: string,
	/**
	 *  rc 에 begin/end 중 하나만 있어 쓰기가 막힌 상태 — 사용자가 손으로
	 *  고쳐야 한다. 이 경우 install 은 실패한다(파일 손상 방지가 우선).
	 */
	block_broken: boolean,
};

/**  우리가 지원하는 셸. 그 외는 조용히 통합을 건너뛴다(터미널은 정상 동작). */
export type ShellKind = "zsh" | "bash" | 
/**  fish·nu·pwsh 등 — 통합 미지원. */
"unsupported";

/**  A shipped unit — a completed feature/refactor journal entry. */
export type ShippedItem = {
	/**  Raw frontmatter type: `feature` | `refactor`. */
	kind: string,
	title: string,
	agent_id: string,
	workday: string,
};

/**  결정적 스킬 후보 — 한 tag 의 반복 작업 클러스터. */
export type SkillCandidate = {
	/**  원본 tag (억제/재조회 키). */
	tag: string,
	/**  tag 의 폴더명 정규화 (`.claude/skills/<slug>/` 제안 위치). */
	slug: string,
	/**  이 tag 가 붙은 일지 수. */
	count: number,
	/**  가장 최근 등장 workday. */
	last_workday: string,
	/**  표본 제목 (최신순, 최대 3). */
	sample_titles: string[],
};

/**  `skills_read` 응답 — 원문 + 보조 파일 목록. */
export type SkillDetail = {
	entry: SkillEntry,
	/**  SKILL.md 원문 (frontmatter 포함). */
	content: string,
	/**  스킬 폴더 내 보조 파일 상대 경로 (SKILL.md 제외, 최대 50개). */
	files: string[],
	/**  SKILL.md 절대 경로 — 외부 에디터로 열 때 사용. */
	skill_md_path: string,
};

/**
 *  LLM 이 만든 스킬 초안. `content` 가 저장용 SKILL.md 전문 — 프런트는
 *  슬러그만 바꿔서 `skills_save(scope=project, <slug>, content, create=true)`
 *  를 부른다 (승인 없이는 어떤 파일도 쓰이지 않는다).
 */
export type SkillDraft = {
	tag: string,
	slug: string,
	/**  frontmatter description (영어 "Use when …" — 자동 발동 트리거). */
	description: string,
	/**  본문만 (frontmatter·마커 제외) — 모달 미리보기용. */
	body_markdown: string,
	/**  frontmatter + 본문 + promoted-from 마커의 저장용 완성본. */
	content: string,
	/**  제안 저장 위치 (`.claude/skills/<slug>/SKILL.md`). */
	rel_path: string,
};

/**  스킬 목록의 한 줄. `dir_name` 이 (scope 내) 조작 키다. */
export type SkillEntry = {
	scope: SkillScope,
	dir_name: string,
	/**  frontmatter `name` (없으면 폴더명). */
	name: string,
	/**  frontmatter `description` (없으면 빈 문자열) — 에이전트 자동 발동 기준. */
	description: string,
	enabled: boolean,
	/**  표시용 경로 — project 는 프로젝트 루트 상대, global 은 `~/…`. */
	display_path: string,
	/**  SKILL.md 를 제외한 보조 파일 수 (참고 문서·스크립트 등). */
	extra_files: number,
};

export type SkillScope = 
/**  `<project>/.claude/skills` — 이 프로젝트에서만 로드. */
"project" | 
/**  `~/.claude/skills` — 모든 프로젝트에서 로드. */
"global";

/**  초안 — 프런트가 그대로 그리고, 승인 시 `content` 를 저장한다. */
export type SkillTriggerDraft = {
	dir_name: string,
	/**  지금 frontmatter 에 있는 description (없으면 빈 문자열). */
	current: string,
	/**  제안된 새 description. */
	proposed: string,
	/**  왜 이렇게 바꾸는지 한두 줄 (한국어 UI 에 그대로 보인다). */
	rationale: string,
	/**  저장용 SKILL.md 전문 — **description 행만 교체**하고 나머지는 바이트 보존. */
	content: string,
};

/**  `skills_list` 응답. 두 스코프를 한 번에 내려 UI 왕복을 줄인다. */
export type SkillsOverview = {
	project: SkillEntry[],
	global: SkillEntry[],
	/**  절대 경로 — 빈 상태 안내·"폴더 열기" 용. */
	project_skills_dir: string,
	global_skills_dir: string,
};

export type SummaryStyle = "standup" | "pr_description" | "weekly_status";

export type SymbolCall = {
	/**  Caller symbol in this file (None = file top-level). */
	from_symbol: string | null,
	kind: string,
	callee: string,
	/**  Resolved defining file path (None = external / unresolved). */
	target_path: string | null,
	estimated: boolean,
};

export type SymbolDef = {
	name: string,
	kind: string,
	start_line: number,
	end_line: number,
	start_byte: number,
	end_byte: number,
};

/**
 *  PR-R1b (A2) — a symbol hit from `search_symbols` (name LIKE over the AST
 *  symbol index). Unlike `SymbolDef` it carries the owning file path.
 */
export type SymbolSearchResult = {
	name: string,
	kind: string,
	file_path: string,
	start_line: number,
	end_line: number,
};

/**  그 탭이 이 창의 스트립을 벗어났다 (또는 드래그가 끝났다) — 캐럿을 지운다. */
export type TabDragLeave = {
	window: string,
};

/**
 *  다른 창에서 끌고 온 탭이 **이 창의 스트립 위**에 있다 (창 간 드래그).
 * 
 *  `x` 는 창 안쪽 왼쪽 위 기준 **논리 px**. 받는 쪽이 웹뷰 줌으로 나눠 CSS px 로
 *  바꾼 뒤, 자기 탭 기하로 삽입 자리를 계산해 캐럿을 그리고 그 인덱스를
 *  `tab_drop_hint` 로 되돌려 준다 — Rust 는 탭 폭을 모르기 때문이다.
 */
export type TabDragOver = {
	window: string,
	x: number | null,
	/**  끌려오는 탭. 자기 탭이면(같은 창 되돌아오기) 무시할 수 있게 실어 보낸다. */
	tab_id: number,
	/**
	 *  끌려오는 탭의 겉모습 — **스트립에 처음 들어선 순간에만** 실린다.
	 * 
	 *  받는 창은 남의 탭 이름을 알 길이 없다(레지스트리도 프로젝트 DB 도 그
	 *  창의 것이 아니다). 그런데 자리표시자에 이름이 없으면 "무엇이 오는지"는
	 *  모른 채 "무언가 온다"만 보인다 — 창이 셋이면 그게 곧 오조준이 된다.
	 * 
	 *  매번 싣지 않는 이유는 값이 DB 조회 한 번이기 때문이다. 포인터는 초당
	 *  수십 번 움직이지만 **겨누는 창이 바뀌는 일**은 드물다. 받는 쪽은 처음
	 *  받은 것을 `TabDragLeave` 까지 들고 있으면 된다.
	 */
	preview: TabPreview | null,
};

/**
 *  탭 스트립이 그릴 정보. 시작 탭은 `project_id: None` 이고 이름은 프런트가
 *  사전에서 붙인다 (백엔드가 UI 문자열을 만들지 않는다).
 */
export type TabInfo = {
	tab_id: number,
	project_id: number | null,
	name: string,
	root_path: string,
	/**
	 *  프로젝트 겉모습 — 탭도 카드와 같은 아이콘·색으로 그린다. 둘 다 id 이고
	 *  `None` 이면 프런트가 이름에서 유도한다 (카드와 같은 규칙).
	 */
	icon: string | null,
	color: string | null,
};

/**
 *  끌려오는 탭을 받는 창이 그리기 위한 최소 정보 — 스트립의 탭과 **같은**
 *  재료다(이름·아이콘·색). 프로젝트 id 를 안 싣는 이유는 받는 창이 그것으로
 *  할 수 있는 일이 없어서다: 아직 자기 탭이 아니라 조회해도 남의 것이다.
 */
export type TabPreview = {
	name: string,
	icon: string | null,
	color: string | null,
	/**  시작 탭인가 — 이름이 비어 있고 아이콘이 고정이라 갈래가 필요하다. */
	is_start: boolean,
};

/**
 *  손에 들려 있던 창을 **놓았다** — 이제 평범한 창이다.
 * 
 *  떼어내는 동안 그 창은 탭 줄만 그리고 화면 마운트를 붙잡고 있었다
 *  (`?tearoff=1`). 이 이벤트가 그 손을 놓아 준다 — 프로젝트 init·워처·자동색인이
 *  그때 비로소 돈다. 끌려다니다 남의 창에 합쳐지면 이 이벤트는 오지 않고 창이
 *  그대로 닫히므로, 그 전부가 아예 시작되지 않는다.
 */
export type TearOffSettled = {
	window: string,
};

/**
 *  터미널을 창으로 떼어낸 프로젝트 집합이 바뀌었다 (2026-08-15).
 * 
 *  셸의 도크·터미널 화면은 이걸 듣고 자리표시자로 바뀐다. 사용자가 분리 창을
 *  OS 의 닫기 버튼으로 닫아도 같은 길로 되돌아온다 — 프런트가 자기 상태를
 *  진실로 삼지 않는 이유다.
 */
export type TerminalWindowsChanged = {
	open: number[],
};

/**  팝오버 → 메인 창 딥링크 (D5). `view` 는 프런트 `UiV2View` 문자열. */
export type TrayNavigate = {
	view: string,
	project_id: number | null,
	/**  `.oculpm/` 상대 일지 경로 — 있으면 해당 일지를 연다. */
	entry_path: string | null,
};

export type WatcherConfig = {
	ignore: string[],
	respect_gitignore: boolean,
	debounce_ms: number,
};

export type WatcherStateView = "running" | "stopped" | "error";

/**
 *  한 창의 탭 구성이 바뀌었다 — 그 창의 프런트가 스트립을 다시 그린다.
 *  이름까지 실어 보내므로 프런트는 후속 조회가 필요 없다.
 */
export type WindowTabsChanged = {
	window: string,
	tabs: TabInfo[],
	active: number | null,
};

export type WindowTabsSnapshot = {
	window: string,
	tabs: TabInfo[],
	active: number | null,
};

/**
 *  v2 U12 (N3) — Today/저널 타임라인의 단일 집계 응답. 기존에 Today 오픈이
 *  [요일당 list 7회 + 오늘 엔트리당 get 1회 + 플랜당 get 1회 + 365일 히트맵]
 *  = 12+N 회 IPC 를 유발하던 것을 이 커맨드 1회로 대체한다.
 */
export type WorkdayBrief = {
	days: WorkdayBucket[],
	/**
	 *  `lines_workday` 로 지정한 워크데이의 라인 증감 합 (미지정 시 0/0).
	 *  diff 사이드카에서 파생된 값 — 프론트매터 `bytes_*` 가 아니다.
	 */
	lines_added: number,
	lines_removed: number,
	/**  활성 플랜의 미완 항목 (진행중 우선) — Today "다음 할 일" + 스탠드업 공유. */
	open_plan_items: OpenPlanItem[],
	/**  프로젝트 전체 일지 수 (365일 히트맵 대체 스칼라). */
	total_entries: number,
};

/**  v2 U12 (N3) — 워크데이 버킷 하나. */
export type WorkdayBucket = {
	workday: string,
	entries: JournalEntrySummary[],
};

/**
 *  워크데이 하나의 정직성 감사 (완성도 라운드 Phase 3, 2026-08-30).
 * 
 *  [`LayerComparison`] 은 세션 하나를 보지만 Today 는 그날 세션 전부를 물어야
 *  해서 세션 수만큼 IPC 를 날리고, 뒤에서는 같은 `file_changes.ndjson` 을
 *  세션 수만큼 다시 파싱했다. 이 구조체는 ndjson 을 **한 번** 읽고 세션별로
 *  갈라 `unrecorded` 만 낸다 — Today 가 읽는 것은 그것뿐이다.
 */
export type WorkdayComparison = {
	workday: string,
	/**
	 *  그날 index 에 변경을 남긴 세션들 (변경이 없는 세션은 없다). `unrecorded`
	 *  가 빈 세션도 들어 있다 — 화면이 거른다.
	 */
	sessions: SessionUnrecorded[],
	/**  세션 전체에 걸친 `unrecorded` 의 합 (중복 경로는 세션마다 센다). */
	unrecorded_total: number,
};

export type WorkdayConfig = {
	/**  IANA timezone name (e.g. `Asia/Seoul`). */
	timezone: string,
	/**  `HH:MM` 24-hour. Late-night coders may use `03:00`. */
	day_starts_at: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

